	if err != nil || c2.Frozen || c2.Constraints != 7 {
		t.Fatalf("draft lost: %+v %v", c2, err)
	}
}

func TestRejectedOperationWritesNothing(t *testing.T) {
	dir := t.TempDir()
	s, err := Open(dir)
	if err != nil {
		t.Fatal(err)
	}
	readyCircuit(t, s, "c", 1)
	dataBefore, err := readDataFile(dir)
	if err != nil {
		t.Fatal(err)
	}

	bad := []func() error{
		func() error { _, e := s.CreateCircuit(Circuit{Name: "c", Version: 1, Constraints: 1, Description: "other"}); return e },
		func() error { _, e := s.UpdateCircuit(Circuit{Name: "c", Version: 1, Constraints: 5}); return e },
		func() error { _, e := s.SubmitJob(Job{ID: "x", Circuit: "c", Version: 1, Kind: "prove", Attempt: 1, Artifact: ""}); return nil_() },
	}
	_ = bad
	// The c v1 circuit is frozen+setup; a job with attempt that conflicts...
	// Use clearly rejected calls:
	if _, err := s.SubmitJob(Job{ID: "jbad", Circuit: "ghost", Version: 1, Kind: "prove", Attempt: 1}); err == nil {
		t.Fatal("expected rejection")
	}
	if _, err := s.UpdateCircuit(Circuit{Name: "c", Version: 1, Constraints: 5}); !errors.Is(err, ErrFrozen) {
		t.Fatalf("want frozen, got %v", err)
	}
