	// record, regardless of the other (ignored-on-existing) count arguments.
	same := Circuit{Name: "transfer", Version: 3, Constraints: 9999, PublicInputs: 9, PrivateInputs: 9, Description: "d3"}
	got, err := s.CreateCircuit(same)
	if err != nil {
