package zkcircuit

import (
	"bufio"
	"bytes"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strconv"
	"strings"
	"sync"
	"testing"
)

// In-process: two open handles on one directory are independent open file
// descriptions with separate flock state. Concurrent creators on disjoint
// keys must all have their committed records preserved.
func TestTwoHandlesConcurrentCreates(t *testing.T) {
	dir := t.TempDir()
	s1, err := Open(dir)
	if err != nil {
		t.Fatal(err)
	}
	s2, err := Open(dir)
	if err != nil {
		t.Fatal(err)
	}
	defer s1.Close()
	defer s2.Close()

	const n = 60
	var wg sync.WaitGroup
	errs := make(chan error, 2*n)
	for i := 0; i < n; i++ {
		wg.Add(2)
		go func(i int) {
			defer wg.Done()
			_, e := s1.CreateCircuit(Circuit{Name: fmt.Sprintf("a%03d", i), Version: 1, Constraints: 1, Description: "x"})
			errs <- e
		}(i)
		go func(i int) {
			defer wg.Done()
			_, e := s2.CreateCircuit(Circuit{Name: fmt.Sprintf("b%03d", i), Version: 1, Constraints: 1, Description: "x"})
			errs <- e
		}(i)
	}
	wg.Wait()
	close(errs)
	for e := range errs {
		if e != nil {
			t.Fatalf("concurrent create: %v", e)
		}
	}

	s3, err := Open(dir)
	if err != nil {
		t.Fatalf("reopen: %v", err)
	}
	defer s3.Close()
	list, err := s3.ListCircuits()
	if err != nil {
		t.Fatal(err)
	}
	if len(list) != 2*n {
		t.Fatalf("lost committed records: want %d, got %d", 2*n, len(list))
	}
}

// The draft/freeze race can only end in one of two complete states:
//  1. the whole new description was committed and then the version was
//     frozen with that description, or
//  2. the freeze landed first and every later update was rejected.
// A half-updated record (constraints from one write, description from
// another, or any update visible while frozen) must never appear.
func TestFreezeUpdateRaceNoPartialState(t *testing.T) {
	for iter := 0; iter < 25; iter++ {
		dir := t.TempDir()
		s, err := Open(dir)
		if err != nil {
			t.Fatal(err)
		}
		if _, err := s.CreateCircuit(Circuit{Name: "c", Version: 1, Constraints: 1, Description: "desc-1"}); err != nil {
			t.Fatal(err)
		}

		var wg sync.WaitGroup
		start := make(chan struct{})
		wg.Add(2)
		go func() {
			defer wg.Done()
			<-start
			for i := 2; i <= 200; i++ {
				_, err := s.UpdateCircuit(Circuit{Name: "c", Version: 1, Constraints: i, Description: fmt.Sprintf("desc-%d", i)})
				if err != nil {
					if !isErr(err, ErrFrozen) {
						t.Errorf("unexpected update error: %v", err)
					}
					return
				}
			}
		}()
		go func() {
			defer wg.Done()
			<-start
			s.FreezeCircuit("c", 1)
		}()
		close(start)
		wg.Wait()

		got, err := s.GetCircuit("c", 1)
		if err != nil {
			t.Fatal(err)
		}
		if !got.Frozen {
			t.Fatalf("iter %d: version not frozen after race", iter)
		}
		wantDesc := fmt.Sprintf("desc-%d", got.Constraints)
		if got.Description != wantDesc {
			t.Fatalf("iter %d: partial update visible: constraints=%d description=%q (want %q)",
				iter, got.Constraints, got.Description, wantDesc)
		}
		if got.Constraints < 1 || got.Constraints > 200 {
			t.Fatalf("iter %d: implausible constraints %d", iter, got.Constraints)
		}
		// Frozen state rejects every further modification.
		if _, err := s.UpdateCircuit(Circuit{Name: "c", Version: 1, Constraints: 777, Description: "hax"}); !isErr(err, ErrFrozen) {
			t.Fatalf("post-freeze update: %v", err)
		}
		s.Close()

		// Reopen and verify the same complete state survived on disk.
		s2, err := Open(dir)
		if err != nil {
			t.Fatalf("iter %d: reopen: %v", iter, err)
		}
		disk, err := s2.GetCircuit("c", 1)
		s2.Close()
		if err != nil || disk != got {
			t.Fatalf("iter %d: disk state %+v != memory state %+v (err=%v)", iter, disk, got, err)
		}
	}
}

// Concurrent submission of identical create requests must never produce a
// conflict error or duplicate records.
func TestConcurrentIdempotentCreate(t *testing.T) {
	dir := t.TempDir()
	s1, _ := Open(dir)
	s2, _ := Open(dir)
	defer s1.Close()
	defer s2.Close()

	var wg sync.WaitGroup
	errs := make(chan error, 20)
	c := Circuit{Name: "same", Version: 1, Constraints: 8, Description: "d"}
	for i := 0; i < 10; i++ {
		wg.Add(2)
		go func() { defer wg.Done(); _, e := s1.CreateCircuit(c); errs <- e }()
		go func() { defer wg.Done(); _, e := s2.CreateCircuit(c); errs <- e }()
	}
	wg.Wait()
	close(errs)
	for e := range errs {
		if e != nil {
			t.Fatalf("idempotent concurrent create failed: %v", e)
		}
	}
	list, _ := s1.ListCircuits()
	if len(list) != 1 {
		t.Fatalf("want exactly 1 record, got %d: %+v", len(list), list)
	}
}

func isErr(err error, target StoreError) bool {
	return err != nil && errorIs(err, target)
}

func errorIs(err, target error) bool {
	type iser interface{ Is(error) bool }
	if se, ok := err.(iser); ok {
		return se.Is(target)
	}
	return false
}

// --- cross-process tests via re-exec -------------------------------------

// TestMain recognizes ZKCIRCUIT_HELPER=<mode>: instead of running tests the
// process performs one scripted workbench session. Acknowledged operations
// are printed as "ACK <token>" lines; the parent verifies every ACK survived.
func TestMain(m *testing.M) {
	switch mode := os.Getenv("ZKCIRCUIT_HELPER"); mode {
	case "writer":
		helperWriter()
	case "crash-writer":
		helperCrashWriter()
	case "setup-job-writer":
		helperSetupJobWriter()
	default:
		os.Exit(m.Run())
	}
}

func helperOpen(dir string) *Store {
	s, err := Open(dir)
	if err != nil {
		fmt.Fprintf(os.Stderr, "helper open: %v\n", err)
		os.Exit(10)
	}
	return s
}

// writer creates circuits named by ZKCIRCUIT_PREFIX with versions 1..N, each
// in its own ACKed transaction.
func helperWriter() {
	dir := os.Getenv("ZKCIRCUIT_DIR")
	prefix := os.Getenv("ZKCIRCUIT_PREFIX")
	n, _ := strconv.Atoi(os.Getenv("ZKCIRCUIT_N"))
	s := helperOpen(dir)
	defer s.Close()
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	for v := 1; v <= n; v++ {
		c, err := s.CreateCircuit(Circuit{Name: prefix, Version: v, Constraints: v, Description: prefix})
		if err != nil {
			fmt.Fprintf(os.Stderr, "helper create: %v\n", err)
			out.Flush()
			os.Exit(11)
		}
		if _, err := s.FreezeCircuit(c.Name, c.Version); err != nil {
			fmt.Fprintf(os.Stderr, "helper freeze: %v\n", err)
			out.Flush()
			os.Exit(12)
		}
		fmt.Fprintf(out, "ACK circuit %s %d\n", prefix, v)
		out.Flush()
	}
}

// setup-job-writer registers setup + prove job for circuits assumed frozen
// by the parent (created by writer helpers).
func helperSetupJobWriter() {
	dir := os.Getenv("ZKCIRCUIT_DIR")
	prefix := os.Getenv("ZKCIRCUIT_PREFIX")
	n, _ := strconv.Atoi(os.Getenv("ZKCIRCUIT_N"))
	s := helperOpen(dir)
	defer s.Close()
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	for v := 1; v <= n; v++ {
		// Setup may race with the freezer; retry until the version is frozen.
		if err := retryFrozen(func() error {
			_, e := s.RecordSetup(prefix, v)
			return e
		}); err != nil {
			fmt.Fprintf(os.Stderr, "helper setup: %v\n", err)
			out.Flush()
			os.Exit(13)
		}
		job := Job{ID: fmt.Sprintf("%s-job-%d", prefix, v), Circuit: prefix, Version: v, Kind: "prove", Attempt: 1}
		stored, err := s.SubmitJob(job)
		if err != nil {
			fmt.Fprintf(os.Stderr, "helper submit: %v\n", err)
			out.Flush()
			os.Exit(14)
		}
		fmt.Fprintf(out, "ACK job %s\n", stored.ID)
		out.Flush()
	}
}

func retryFrozen(fn func() error) error {
	var last error
	for i := 0; i < 500; i++ {
		last = fn()
		if last == nil {
			return nil
		}
		if !isErr(last, ErrNotFrozen) && !isErr(last, ErrNotFound) {
			return last
		}
	}
	return last
}

// crash-writer loops creates/freeze on distinct versions until the parent
// kills it; every ACK line names a record that must survive the kill.
func helperCrashWriter() {
	dir := os.Getenv("ZKCIRCUIT_DIR")
	prefix := os.Getenv("ZKCIRCUIT_PREFIX")
	s := helperOpen(dir)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	for v := 1; ; v++ {
		if _, err := s.CreateCircuit(Circuit{Name: prefix, Version: v, Constraints: v, Description: prefix}); err != nil {
			fmt.Fprintf(os.Stderr, "crash writer create: %v\n", err)
			return
		}
		if _, err := s.FreezeCircuit(prefix, v); err != nil {
			fmt.Fprintf(os.Stderr, "crash writer freeze: %v\n", err)
			return
		}
		fmt.Fprintf(out, "ACK circuit %s %d\n", prefix, v)
		out.Flush()
	}
}

type ack struct {
	kind string
	args string
}

func runHelper(t *testing.T, dir, mode string, env ...string) ([]ack, string) {
	t.Helper()
	cmd := exec.Command(os.Args[0], "-test.run=TestHelperProcess")
	cmd.Env = append(os.Environ(),
		"ZKCIRCUIT_HELPER="+mode,
		"ZKCIRCUIT_DIR="+dir,
	)
	cmd.Env = append(cmd.Env, env...)
	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	if err := cmd.Run(); err != nil {
		t.Fatalf("helper %s failed: %v\nstderr:\n%s", mode, err, stderr.String())
	}
	return parseAcks(t, stdout.Bytes()), ""
}

func parseAcks(t *testing.T, raw []byte) []ack {
	t.Helper()
	var acks []ack
	for _, line := range strings.Split(strings.TrimSpace(string(raw)), "\n") {
		if line == "" {
			continue
		}
		if !strings.HasPrefix(line, "ACK ") {
			t.Fatalf("unexpected helper output: %q", line)
		}
		rest := strings.TrimPrefix(line, "ACK ")
		parts := strings.SplitN(rest, " ", 2)
		acks = append(acks, ack{kind: parts[0], args: parts[1]})
	}
	return acks
}

// Two real processes create disjoint circuit versions; a third registers
// setups and submits jobs. Everything every process acknowledged must be in
// the final directory, with no duplicates.
func TestCrossProcessWriters(t *testing.T) {
	if os.Getenv("ZKCIRCUIT_HELPER") != "" {
		return
	}
	dir := filepath.Join(t.TempDir(), "bench")
	const per = 25
	cmds := make([]*exec.Cmd, 0, 3)
	var outs []bytes.Buffer
	for i, prefix := range []string{"aaa", "bbb"} {
		cmd, out := startHelper(dir, "writer",
			"ZKCIRCUIT_PREFIX="+prefix, "ZKCIRCUIT_N="+strconv.Itoa(per))
		cmds = append(cmds, cmd)
		outs = append(outs, *out)
		_ = i
	}
	for _, cmd := range cmds {
		if err := cmd.Wait(); err != nil {
			t.Fatalf("writer: %v", err)
		}
	}
	var allAcks []ack
	for _, out := range outs {
		allAcks = append(allAcks, parseAcks(t, out.Bytes())...)
	}

	// Now two concurrent setup/job processes.
	jobCmds := make([]*exec.Cmd, 0, 2)
	outs = outs[:0]
	for _, prefix := range []string{"aaa", "bbb"} {
		cmd, out := startHelper(dir, "setup-job-writer",
			"ZKCIRCUIT_PREFIX="+prefix, "ZKCIRCUIT_N="+strconv.Itoa(per))
		jobCmds = append(jobCmds, cmd)
		outs = append(outs, *out)
	}
	for _, cmd := range jobCmds {
		if err := cmd.Wait(); err != nil {
			t.Fatalf("job writer: %v", err)
		}
	}
	for _, out := range outs {
		allAcks = append(allAcks, parseAcks(t, out.Bytes())...)
	}

	s, err := Open(dir)
	if err != nil {
		t.Fatalf("final open: %v", err)
	}
	defer s.Close()
	circuits, err := s.ListCircuits()
	if err != nil {
		t.Fatal(err)
	}
	if len(circuits) != 2*per {
		t.Fatalf("want %d circuits, got %d", 2*per, len(circuits))
	}
	jobs, err := s.ListJobs()
	if err != nil {
		t.Fatal(err)
	}
	if len(jobs) != 2*per {
		t.Fatalf("want %d jobs, got %d", 2*per, len(jobs))
	}
	for _, c := range circuits {
		if !c.Frozen {
			t.Fatalf("circuit %s v%d not frozen", c.Name, c.Version)
		}
	}

	// Every acknowledged record is present exactly once; every stored job
	// still pins the exact version at submission.
	ackCircuit := make(map[string]int)
	ackJob := make(map[string]int)
	for _, a := range allAcks {
		switch a.kind {
		case "circuit":
			ackCircuit[a.args]++
		case "job":
			ackJob[a.args]++
		}
	}
	for k, n := range ackCircuit {
		if n != 1 {
			t.Fatalf("circuit ack %q seen %d times", k, n)
		}
		parts := strings.Split(k, " ")
		v, _ := strconv.Atoi(parts[1])
		if _, err := s.GetCircuit(parts[0], v); err != nil {
			t.Fatalf("acknowledged circuit %s missing: %v", k, err)
		}
	}
	for id, n := range ackJob {
		if n != 1 {
			t.Fatalf("job ack %q seen %d times", id, n)
		}
		if _, err := s.GetJob(id); err != nil {
			t.Fatalf("acknowledged job %s missing: %v", id, err)
		}
	}
}

func startHelper(dir, mode string, extra ...string) (*exec.Cmd, *bytes.Buffer) {
	cmd := exec.Command(os.Args[0], "-test.run=TestHelperProcess")
	cmd.Env = append(os.Environ(),
		"ZKCIRCUIT_HELPER="+mode,
		"ZKCIRCUIT_DIR="+dir,
	)
	cmd.Env = append(cmd.Env, extra...)
	var out bytes.Buffer
	cmd.Stdout = &out
	cmd.Stderr = &failWriter{}
	if err := cmd.Start(); err != nil {
		panic(err)
	}
	return cmd, &out
}

type failWriter struct{}

func (failWriter) Write(p []byte) (int, error) { return len(p), nil }

// Kill writers mid-flight with SIGKILL. Reopening afterwards must show a
// complete state, and every record the victims acknowledged before dying
// must still be present.
func TestCrossProcessCrashRecovery(t *testing.T) {
	if os.Getenv("ZKCIRCUIT_HELPER") != "" {
		return
	}
	dir := filepath.Join(t.TempDir(), "bench")

	const victims = 6
	cmds := make([]*exec.Cmd, 0, victims)
	outs := make([]*bytes.Buffer, 0, victims)
	for i := 0; i < victims; i++ {
		cmd, out := startHelper(dir, "crash-writer",
			"ZKCIRCUIT_PREFIX="+fmt.Sprintf("p%02d", i))
		cmds = append(cmds, cmd)
		outs = append(outs, out)
	}
	// Let them run briefly, then SIGKILL everyone at different points.
	killDelayMS(t, cmds)

	var acks []ack
	for i, cmd := range cmds {
		_ = cmd.Wait()
		acks = append(acks, parseAcks(t, outs[i].Bytes())...)
	}

	// The directory must reopen cleanly: only a complete old or new state.
	s, err := Open(dir)
	if err != nil {
		t.Fatalf("reopen after SIGKILL storm: %v", err)
	}
	defer s.Close()
	for _, a := range acks {
		parts := strings.Split(a.args, " ")
		v, _ := strconv.Atoi(parts[1])
		c, err := s.GetCircuit(parts[0], v)
		if err != nil {
			t.Fatalf("acknowledged record %q lost after crash: %v", a.args, err)
		}
		if !c.Frozen || c.Constraints != v || c.Description != parts[0] {
			t.Fatalf("acknowledged record %q incomplete: %+v", a.args, c)
		}
	}
